rule.definition:
if(
  or(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!filter),
    len(ri!filter)<#"_a-0000e6d2-8270-8000-9c03-011c48011c48_3895397"
  ),
  #"SYSTEM_SYSRULES_dataSubset"(data: {}, identifiers: {}),
  a!localVariables(
    local!results: #"SYSTEM_SYSRULES_queryEntity_v1"(
      entity: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3851752",
      query: #"SYSTEM_SYSRULES_query"(
        selection: #"SYSTEM_SYSRULES_querySelection"(
          columns: {
            #"SYSTEM_SYSRULES_queryColumn"(field:"fullName")
          }
        ),
        paginginfo: #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: -1
        ),
        filter: #"SYSTEM_SYSRULES_queryFilter"(
          field: "fullName",
          operator: "starts with",
          value: ri!filter
        )
      )
    ), 
    local!filteredData: reject(
      fn!isnull,
      union(index(local!results.data, "fullName", {}), index(local!results.data, "fullName", {}))
    ),
    #"SYSTEM_SYSRULES_dataSubset"(
      data: local!filteredData,
      identifiers: local!filteredData
    )
  )
)
